CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 ANY, c1 INTEGER CHECK(c1 IS NULL OR length(c1) < 40), c2 ANY, c3 INTEGER DEFAULT 'd') STRICT;
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES('zeta', x'33', 'naïve', 24);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES('delta', -305, 0.1, -43);
