CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INTEGER UNIQUE, c1 INTEGER COLLATE NOCASE, c2 NUMERIC NOT NULL DEFAULT 0, c3  CHECK(c3 IS NULL OR length(c3) < 40), c4 INT);
