SELECT json_valid('{"a":}'), json('{"a":}'), json_type('{"a":}'), json_array_length('{"a":}'), json_extract('{"a":}', '$.a', '$[1]', '$.b[2].c'), '{"a":}' -> '$.b', '{"a":}' ->> '$.n.m.o';
SELECT key, value, type FROM json_each('{"a":}') ORDER BY key;
SELECT json_set('{"a":}', '$.z', 1), json_insert('{"a":}', '$.a', 2), json_remove('{"a":}', '$.a'), json_patch('{"a":1}', '{"b":2}');
SELECT json_group_array(id), json_group_object(CAST(id AS TEXT), c2) FROM t1;
SELECT json_object('id', id, 'v', c1) FROM t1 ORDER BY id LIMIT 4;
